// @vitest-environment jsdom
import RAPIER from '@dimforge/rapier3d-compat';
import * as THREE from 'three';
import { beforeAll, describe, expect, it } from 'vitest';
import { planShot } from '../ai/BotPlanner';
import { botProfileForRating } from '../ai/Matchmaking';
import { HoleSceneBuilder } from '../core/HoleSceneBuilder';
import { greenHillsCourse } from '../courses/data/green-hills';
import { HoleSystem } from '../gameplay/HoleSystem';
import { InputManager } from '../input/InputManager';
import { GolfBallPhysics } from '../physics/GolfBallPhysics';
import { PhysicsWorld } from '../physics/PhysicsWorld';
import { Game, chargeForPower, rolledVelocity } from './Game';
import { HoleRuntime } from './HoleRuntime';

const STEP = 1 / 60;
const BALL_OPTIONS = { mass: 0.75, friction: 0.5, restitution: 0.45, rollingResistance: 0, airResistance: 0 };

beforeAll(async () => {
  await RAPIER.init();
});

describe('hole runtime', () => {
  it('rolls planned shots into the cup of the opening hole', () => {
    const hole = greenHillsCourse.holes[0];
    if (!hole) throw new Error('green-hills has no holes');
    const physics = new PhysicsWorld();
    const builder = new HoleSceneBuilder();
    const runtime = new HoleRuntime(physics, hole, builder);
    const ball = new GolfBallPhysics(physics, hole.spawn, BALL_OPTIONS);
    const holeSystem = new HoleSystem();
    const profile = botProfileForRating(2400, { id: 'bot-test', personality: 'balanced' });

    let strokes = 0;
    let holed = false;
    while (strokes < 12 && !holed) {
      const plan = planShot(profile, {
        playerId: 'bot-test',
        hole,
        ballPosition: ball.position,
        clientSequence: strokes + 1,
        issuedAt: 0,
        seed: 'test:' + String(strokes),
      });
      expect(ball.applyShot(plan.command.direction, chargeForPower(plan.command.normalizedPower)).accepted).toBe(true);
      strokes += 1;
      for (let step = 0; step < 60 * 20; step += 1) {
        physics.step(STEP, (fixed) => {
          runtime.update(fixed);
          const rolled = rolledVelocity(ball.velocity, runtime.decelerationAt(ball.position), fixed);
          if (rolled) ball.body.setLinvel(rolled, true);
          ball.update(fixed);
        });
        if (holeSystem.isBallHoled(hole, ball.position, ball.speed)) {
          holed = true;
          break;
        }
        if (runtime.hazardAt(ball.position) || holeSystem.isOutsideBounds(hole, ball.position)) {
          ball.reset(hole.spawn);
          break;
        }
        if (ball.canShoot) break;
      }
    }

    expect(holed).toBe(true);
    runtime.dispose();
    builder.dispose();
    physics.dispose();
  }, 60000);
});

describe('Game', () => {
  it('plays a one hole match from keyboard putts to the results table', async () => {
    const hole = greenHillsCourse.holes[0];
    if (!hole) throw new Error('green-hills has no holes');
    const overlay = document.createElement('div');
    document.body.append(overlay);
    const input = new InputManager({});
    const camera = new THREE.PerspectiveCamera(60, 1.5, 0.1, 400);
    const game = await Game.create({
      renderer: {} as unknown as THREE.WebGLRenderer,
      camera,
      input,
      overlayRoot: overlay,
      courseId: 'green-hills',
      holeCount: 1,
      humanCount: 1,
      botCount: 0,
      controlScheme: 'hold-to-charge',
    });

    const results = overlay.querySelector<HTMLElement>('.match-results');
    const status = overlay.querySelector<HTMLElement>('.hud-status');
    const ballMesh = game.scene.getObjectByName('ball-local-player');
    expect(results).not.toBeNull();
    expect(ballMesh).toBeDefined();

    let charge = 0;
    let shots = 0;
    let maxZ = -Infinity;
    for (let frame = 0; frame < 30000; frame += 1) {
      if (results?.hidden === false) break;
      if (charge > 0) {
        charge += 1;
        if (charge > 30) {
          window.dispatchEvent(new KeyboardEvent('keyup', { code: 'Space' }));
          charge = 0;
          shots += 1;
        }
      } else if (status?.dataset.ready === 'true') {
        window.dispatchEvent(new KeyboardEvent('keydown', { code: 'Space' }));
        charge = 1;
      }
      game.frame(STEP);
      input.endFrame();
      maxZ = Math.max(maxZ, ballMesh?.position.z ?? -Infinity);
    }

    expect(shots).toBeGreaterThan(0);
    expect(maxZ).toBeGreaterThan(hole.spawn.z + 2);
    expect(results?.hidden).toBe(false);
    expect(results?.textContent).toContain('MATCH COMPLETE');
    expect(results?.textContent).toContain('Green Hills');
    expect(results?.textContent).toContain('strokes');
    expect(overlay.querySelector('.hud-hole')?.textContent).toContain('HOLE 1/1');

    game.dispose();
    input.dispose();
    overlay.remove();
  }, 120000);
});
